-- Migration 076 — troop families who opted in to updates (/troop2514).
--
-- The "Get updates" tab: a parent leaves their name, email and (optionally) a
-- phone number and ticks the consent box. The leaders see the list in the
-- Leaders tab and send updates themselves. Nothing here is a Host Hampton
-- contact: no `contacts` row, no Brevo, no Quo, no sequence.
--
-- ── WHAT IS DELIBERATE ──
--
--   1. `email` is stored as typed. `email_key` is its lowercase, GENERATED by
--      the database, and (troop, email_key) is unique — so a parent signing up
--      twice, in any capitals, updates their row instead of adding a second one,
--      and the route's upsert never has to filter an email column itself.
--   2. `consent_text` is the exact sentence the parent agreed to, and
--      `consented_at` when. A text from a leader rests on it.
--
-- Safe to re-run.

BEGIN;

CREATE TABLE IF NOT EXISTS public.troop_families (
  id            uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  troop         text NOT NULL,
  parent_name   text NOT NULL,
  scout_name    text,
  email         text NOT NULL,
  email_key     text GENERATED ALWAYS AS (lower(email)) STORED,
  phone         text,
  consent_text  text NOT NULL,
  consented_at  timestamptz NOT NULL DEFAULT now(),
  created_at    timestamptz NOT NULL DEFAULT now()
);

ALTER TABLE public.troop_families DROP CONSTRAINT IF EXISTS troop_families_troop_check;
ALTER TABLE public.troop_families ADD CONSTRAINT troop_families_troop_check CHECK (troop ~ '^[0-9]{3,6}$');

ALTER TABLE public.troop_families DROP CONSTRAINT IF EXISTS troop_families_email_key_unique;
ALTER TABLE public.troop_families ADD CONSTRAINT troop_families_email_key_unique UNIQUE (troop, email_key);

ALTER TABLE public.troop_families ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Service role full access on troop_families" ON public.troop_families;
CREATE POLICY "Service role full access on troop_families" ON public.troop_families
  USING (auth.role() = 'service_role') WITH CHECK (auth.role() = 'service_role');

COMMIT;
